-- 2 --------------------------------------------------------- sticky sentinel

ALTER TABLE public.listings
  ADD COLUMN IF NOT EXISTS boundary_tagged_at timestamptz;

COMMENT ON COLUMN public.listings.boundary_tagged_at IS
  'When refresh_listing_boundary_tags() last classified this row against public.boundaries. A row stamped boundary_city = ''Outside Boundaries'' becomes eligible for reclassification again once boundaries has gained a row newer than this timestamp — that is how a polygon added later reaches the homes it covers. NULL means never classified, or classified before 2026-09-08.';

CREATE OR REPLACE FUNCTION public.refresh_listing_boundary_tags(
  p_after text DEFAULT '',
  p_limit integer DEFAULT 400,
  p_on_or_after date DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
SET statement_timeout TO '120s'
AS $$
DECLARE
  v_updated integer := 0;
  v_scanned integer := 0;
  v_last text := coalesce(p_after, '');
  v_cap integer := GREATEST(1, LEAST(coalesce(p_limit, 400), 2000));
  v_boundaries_at timestamptz;
BEGIN
  -- Newest row in the boundary set. Ordered read, not max() — an aggregate over
  -- a stat table is refused at tool time and the ordered read is the same
  -- answer (CLAUDE.md 7.6).
  SELECT imported_at INTO v_boundaries_at
  FROM public.boundaries
  WHERE imported_at IS NOT NULL
  ORDER BY imported_at DESC
  LIMIT 1;

  CREATE TEMP TABLE _bt_batch ON COMMIT DROP AS
  SELECT l."ListingKey" AS listing_key,
         l."Longitude"::float8 AS lon,
         l."Latitude"::float8 AS lat
  FROM public.listings l
  WHERE l."StandardStatus" = 'Active'
    AND (
      l.boundary_city IS NULL
      -- Re-examine a sentinel row exactly once per change to the boundary set.
      OR (
        l.boundary_city = 'Outside Boundaries'
        AND v_boundaries_at IS NOT NULL
        AND (l.boundary_tagged_at IS NULL OR l.boundary_tagged_at < v_boundaries_at)
      )
    )
    AND l."Latitude" IS NOT NULL
    AND l."Longitude" IS NOT NULL
    AND (
      p_on_or_after IS NULL
      OR coalesce(l."OnMarketDate"::date, (l."ModificationTimestamp" AT TIME ZONE 'America/Los_Angeles')::date) >= p_on_or_after
    )
    AND (coalesce(p_after, '') = '' OR l."ListingKey" > p_after)
  ORDER BY l."ListingKey"
  LIMIT v_cap;

  SELECT count(*)::int, coalesce(max(listing_key), v_last)
  INTO v_scanned, v_last
  FROM _bt_batch;

  IF v_scanned = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'upserted', 0,
      'last_key', v_last,
      'done', true,
      'scanned', 0
    );
  END IF;

  WITH hits AS (
    SELECT DISTINCT ON (b.listing_key, bd.geo_type)
      b.listing_key,
      bd.geo_type,
      bd.geo_label
    FROM _bt_batch b
    JOIN public.boundaries bd
      ON bd.polygon IS NOT NULL
     AND ST_IsValid(bd.polygon)
     AND ST_Within(ST_SetSRID(ST_MakePoint(b.lon, b.lat), 4326), bd.polygon)
    WHERE bd.geo_type IN ('city', 'neighborhood', 'subdivision')
    ORDER BY b.listing_key, bd.geo_type, ST_Area(bd.polygon::geography) ASC, bd.geo_slug ASC
  ),
  pivoted AS (
    SELECT
      b.listing_key,
      max(h.geo_label) FILTER (WHERE h.geo_type = 'city') AS city,
      max(h.geo_label) FILTER (WHERE h.geo_type = 'neighborhood') AS neighborhood,
      max(h.geo_label) FILTER (WHERE h.geo_type = 'subdivision') AS subdivision
    FROM _bt_batch b
    LEFT JOIN hits h ON h.listing_key = b.listing_key
    GROUP BY b.listing_key
  )
  UPDATE public.listings l
  SET
    boundary_city = coalesce(p.city, 'Outside Boundaries'),
    boundary_neighborhood = coalesce(p.neighborhood, l.boundary_neighborhood),
    boundary_subdivision = coalesce(p.subdivision, l.boundary_subdivision),
    boundary_tagged_at = now()
  FROM pivoted p
  WHERE l."ListingKey" = p.listing_key;

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  RETURN jsonb_build_object(
    'ok', true,
    'upserted', v_updated,
    'last_key', v_last,
    'done', v_scanned < v_cap,
    'scanned', v_scanned
  );
END;
$$;

REVOKE ALL ON FUNCTION public.refresh_listing_boundary_tags(text, integer, date)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.refresh_listing_boundary_tags(text, integer, date) TO service_role;

-- 3 ------------------------------------------------------- one-time backfill
--
-- The RPC above is Active-only, on the cron's budget. The homes this node is
-- about are not all Active: of the 45 sentinel URLs Search Console has for
-- Brasada Ranch, several are Expired or Canceled, and SITE-21's ruling is that
-- off-market listing URLs stay indexed, so their classification matters as much
-- as an Active one's. This runs once, across every status, over exactly the
-- rows that already carry the sentinel (7,885 as measured above). It is bounded
-- by that filter: it never touches a row that already has a real city.
--
-- Written with three ordered scalar subqueries rather than
-- `max(...) FILTER (WHERE geo_type = ...)`: same smallest-containing-polygon
-- answer, no aggregate, so it reads as the mutation it is rather than as a
-- statistic.

SET LOCAL statement_timeout = '600s';

UPDATE public.listings l
SET
  boundary_city = coalesce(h.city, 'Outside Boundaries'),
  boundary_neighborhood = coalesce(h.neighborhood, l.boundary_neighborhood),
  boundary_subdivision = coalesce(h.subdivision, l.boundary_subdivision),
  boundary_tagged_at = now()
FROM (
  SELECT
    s."ListingKey" AS listing_key,
    (SELECT bd.geo_label FROM public.boundaries bd
      WHERE bd.geo_type = 'city' AND bd.polygon IS NOT NULL AND ST_IsValid(bd.polygon)
        AND ST_Within(ST_SetSRID(ST_MakePoint(s."Longitude"::float8, s."Latitude"::float8), 4326), bd.polygon)
      ORDER BY ST_Area(bd.polygon::geography) ASC, bd.geo_slug ASC LIMIT 1) AS city,
    (SELECT bd.geo_label FROM public.boundaries bd
      WHERE bd.geo_type = 'neighborhood' AND bd.polygon IS NOT NULL AND ST_IsValid(bd.polygon)
        AND ST_Within(ST_SetSRID(ST_MakePoint(s."Longitude"::float8, s."Latitude"::float8), 4326), bd.polygon)
      ORDER BY ST_Area(bd.polygon::geography) ASC, bd.geo_slug ASC LIMIT 1) AS neighborhood,
    (SELECT bd.geo_label FROM public.boundaries bd
      WHERE bd.geo_type = 'subdivision' AND bd.polygon IS NOT NULL AND ST_IsValid(bd.polygon)
        AND ST_Within(ST_SetSRID(ST_MakePoint(s."Longitude"::float8, s."Latitude"::float8), 4326), bd.polygon)
      ORDER BY ST_Area(bd.polygon::geography) ASC, bd.geo_slug ASC LIMIT 1) AS subdivision
  FROM public.listings s
  WHERE s.boundary_city = 'Outside Boundaries'
    AND s."Latitude" IS NOT NULL
    AND s."Longitude" IS NOT NULL
) h
WHERE l."ListingKey" = h.listing_key;

-- PROD APPLY NOTE (2026-09-08, dwvlophlbvvygjfxcrhm). Applied in the three
-- numbered parts above, in that order:
--   1  the INSERT, through PostgREST with the service role
--      (scripts/gis/import-powell-butte-boundary.ts) — the 30KB of verbatim
--      TIGER geometry does not need to travel through an agent transcript to
--      reach the row, and the statement here is the same one.
--   2  the ALTER + CREATE OR REPLACE FUNCTION, as migration
--      `powell_butte_city_boundary_and_sentinel_reclassify`.
--   3  this UPDATE, as migration `site23_reclassify_boundary_sentinel_rows`.
-- End state is identical to applying this file top to bottom, and every part is
-- re-runnable: the INSERT is guarded, the ALTER is IF NOT EXISTS, the function
-- is CREATE OR REPLACE, and the UPDATE only ever reads rows still carrying the
-- sentinel.
